// Axes: analysis, practice, experimentation, people, drive, independence, risk control.
// Each question observes one axis twice, or one of five axes with an extra context.
export const questions = [
{axis:0,title:'The brief is vague. What do you do first?',options:['Make a rough screen and learn by doing.','Ask for an example of the desired outcome.','Clarify the goal and the main constraint.','Map the assumptions and dependencies before designing.'],values:[0,1,2,3]},
{axis:1,title:'You have an afternoon to improve a design skill. How do you spend it?',options:['Try something outside my usual practice.','Study a few strong examples and note what works.','Rebuild an example and ask for feedback.','Repeat one difficult exercise until I improve.'],values:[0,1,2,3]},
{axis:2,title:'A familiar flow is underperforming. Where do you start?',options:['Refine its existing structure and details.','Change one part while keeping the pattern.','Combine ideas from other products into a new approach.','Prototype a substantially different direction.'],values:[0,1,2,3]},
{axis:3,title:'A teammate is stuck and your own deadline is close. What is most like you?',options:['Protect my focus and share a resource.','Offer a quick review, then return to my task.','Set aside time to work through the blocker together.','Help them regain momentum, even if my own work has to move.'],values:[0,1,2,3]},
{axis:4,title:'A direction you believe in is rejected. What do you tend to do?',options:['Move to a more promising opportunity.','Make one focused revision and reassess.','Try several alternatives to find a way through.','Keep working at it until I can prove or disprove the idea.'],values:[0,1,2,3]},
{axis:5,title:'When do you do your best thinking?',options:['In a live conversation with other people.','After a short discussion, followed by solo time.','Mostly alone, with a few deliberate check-ins.','With uninterrupted ownership from exploration to proposal.'],values:[0,1,2,3]},
{axis:6,title:'There is time for only one more thing before launch. You choose…',options:['A bold experiment that could teach us something new.','A quick check of the main interaction.','Fixing the most likely sources of user confusion.','Checking failure states and protecting the critical flow.'],values:[0,1,2,3]},
{axis:0,title:'Two solutions both look promising. How do you break the tie?',options:['Build the one I am most excited to try.','Get a quick outside reaction.','Compare them against the main user goal.','Make the trade-offs and second-order effects explicit.'],values:[0,1,2,3]},
{axis:1,title:'Your first prototype is not working. What is your next move?',options:['Drop it and explore another direction.','Find a useful reference to adapt.','Diagnose the weak point and revise it carefully.','Work through repeated feedback cycles until the execution holds up.'],values:[0,1,2,3]},
{axis:2,title:'You find a strong solution in another product. What happens next?',options:['Use the established pattern as consistently as possible.','Adjust its details to fit our constraints.','Combine it with other references to make a better fit.','Use it as a starting point for a different experiment.'],values:[0,1,2,3]},
{axis:3,title:'A review becomes tense. What is your natural role?',options:['Separate the personal reactions from the design facts.','Bring the discussion back to a concrete decision.','Help each person explain their point of view.','Make sure quieter people feel safe enough to speak.'],values:[0,1,2,3]},
{axis:6,title:'A last-minute request changes the scope. You usually…',options:['Try it quickly and see what happens.','Adapt the design as I go.','Check the impact and agree on a smaller change.','Protect the critical requirements and document the trade-off.'],values:[0,1,2,3]}
];
export function profileFor(answers){const sums=Array(7).fill(0),counts=Array(7).fill(0);answers.forEach((a,i)=>{if(Number.isInteger(a)&&a>=0&&a<4){let q=questions[i];sums[q.axis]+=q.values[a];counts[q.axis]++;}});return sums.map((s,i)=>counts[i]?s/counts[i]:1.5);}
export function rank(answers){let p=profileFor(answers);return characters.map(c=>({character:c,distance:c.profile.reduce((s,v,i)=>s+(p[i]-v)**2,0)})).sort((a,b)=>a.distance-b.distance||a.character.id.localeCompare(b.character.id));}
export const reasons=[['You prefer learning through action.','You start with a concrete point of reference.','You clarify the goal before committing.','You examine assumptions and trade-offs.'],['You learn by exploring unfamiliar approaches.','You learn from strong examples.','You refine your work through focused feedback.','You build skill through repeated practice.'],['You value consistency and established patterns.','You favour controlled, incremental changes.','You adapt and combine useful ideas.','You are comfortable trying a new direction.'],['You protect space for objective, focused work.','You bring collaboration back to a practical task.','You make time to understand other perspectives.','You give people support and room to contribute.'],['You redirect effort when another path looks stronger.','You reassess after a focused attempt.','You persist through several alternatives.','You are driven to work through difficult obstacles.'],['You think through ideas with other people.','You balance discussion with individual focus.','You prefer autonomy with deliberate check-ins.','You value deep, independent ownership.'],['You accept uncertainty to learn quickly.','You adapt while checking the main interaction.','You check impact before committing.','You protect critical requirements and failure states.']];
export function explanations(answers,c){const p=profileFor(answers);return p.map((v,i)=>({axis:i,d:Math.abs(v-c.profile[i])})).sort((a,b)=>a.d-b.d||a.axis-b.axis).slice(0,3).map(x=>reasons[x.axis][Math.round(p[x.axis])]);}

export function portraitSpec(c){const extra=c.index>=14;const index=extra?c.index-14:c.index;return {src:extra?"assets/portraits-legends.png":"assets/portraits-manga.png",index,cols:4,rows:extra?2:4};}
export function portraitStyle(c){const p=portraitSpec(c);return `background-image:url(${p.src});background-size:${p.cols*100}% ${p.rows*100}%;background-position:${p.index%p.cols/(p.cols-1)*100}% ${Math.floor(p.index/p.cols)/(p.rows-1)*100}%`;}
